custom_css:
/* === 史努比的晚安 (Snoopy's Goodnight) 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影.=== */

/* --- 1. 字体引入 --- */
@import url('https://fonts.googleapis.com/css2?family=Mali:wght@400;600&family=Quicksand:wght@400;600&display=swap'); 
@import url("https://fontsapi.zeoseven.com/200/main/result.css"); 
@import url("https://fontsapi.zeoseven.com/45/main/result.css");  
@import url("https://fontsapi.zeoseven.com/46/main/result.css");  
@import url("https://fontsapi.zeoseven.com/506/main/result.css"); 

/* --- 2. 核心梦境颜色与样式变量 --- */
:root {
    --theme-bg-color: #F0F8FF; 
    --theme-bg-mid: #BBD6F0; 
    --card-bg: rgba(255, 255, 255, 0.85); 
    --accent-blue: #5BA4E5; 
    --accent-soft: #89B4D8; 
    --text-main: #2C3E50; 
    --text-subtle: #5D7B9D; 

    --font-english-script: 'Mali', cursive;
    --font-english-serif: 'Quicksand', sans-serif;
    --font-main: "cjkFonts 全瀨體", var(--font-english-serif), sans-serif;
    --font-quote: "YEFONTXiaoShiTou", var(--font-english-script), cursive;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "PING FANG MENG MNEG DA", var(--font-english-serif), sans-serif;
}

/* --- 3. 全局样式：去阴影、去边框、星空云朵背景 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg-color) !important; 
    background-image: url('https://images.unsplash.com/photo-1513628253939-010e64ac66cd?q=80&w=2000&auto=format&fit=crop'); 
    background-size: cover;
    background-position: center top;
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
body::after {
    content: ''; position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
    background: radial-gradient(circle at 50% -20%, rgba(255,255,255,0.6), transparent 80%);
    pointer-events: none; z-index: 9999; mix-blend-mode: soft-light;
}

#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--accent-blue); font-weight: normal; }

/* --- 4. 顶部导航栏 & 抽屉背景 --- */
#top-settings-holder { position:relative; background-color: rgba(255, 255, 255, 0.5); backdrop-filter: blur(12px); border: none !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1); }
.drawer-icon.fa-fw:hover { transform: translateY(-3px) scale(1.05); filter: brightness(1.2) drop-shadow(0 0 5px rgba(255,255,255,0.8)); }

.drawer-icon.fa-sliders, #ai-config-button .drawer-icon, .drawer-icon.fa-font, #advanced-formatting-button .drawer-icon, .drawer-icon.fa-user, #user-settings-button .drawer-icon, .drawer-icon.fa-cubes, #extensions-settings-button .drawer-icon, .drawer-icon.fa-face-smile, #persona-management-button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260508/oPBb/1555X1479/2026-05-08%2520172815.png/webp'); 
}
.drawer-icon.fa-plug, #sys-settings-button .drawer-icon, .drawer-icon.fa-book-atlas, #WI-SP-button .drawer-icon, .drawer-icon.fa-image, .drawer-icon.fa-panorama, .drawer-icon.fa-bars-progress, #table_database_settings_drawer .drawer-icon, .drawer-icon.fa-address-card, #character_popup_button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260508/WRPO/1461X1448/2026-05-08%2520172827.png/webp'); 
}

.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(255, 255, 255, 0.8), rgba(255, 255, 255, 0.85)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260508/CmlK/1094X745/086d393ceb574f8e7a1da3ac963113d3.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 12px !important; color: var(--text-main) !important;
}

/* --- 5. 底部悬浮输入栏 --- */
#form_sheld { position: absolute !important; bottom: 10px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { width: 90% !important; max-width: 800px !important; pointer-events: auto; }

#send_form, body.no-blur #send_form { 
    border-radius: 25px !important; 
    background-color: rgba(255, 255, 255, 0.6) !important; 
    padding: 10px 15px !important; 
    backdrop-filter: blur(20px) !important; 
    -webkit-backdrop-filter: blur(20px) !important; 
    border: none !important; 
    box-shadow: none !important; 
    transition: all 0.5s ease !important; 
}
#send_form:hover, body.no-blur #send_form:hover { transform: translateY(-5px); background-color: rgba(255, 255, 255, 0.85) !important; }

#rightSendForm, #leftSendForm { gap: 10px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; font-size: 1rem !important; box-shadow: none !important; }

#nonQRFormItems { position: relative; display: flex; align-items: center; justify-content: center; width: 100%; }
#send_textarea::placeholder { color: transparent !important; text-shadow: none !important; }

/* 完美居中且自适应的伪提示词 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: 'Goodnight Snoopy, wandering in sweet dreams... ☾⋆⁺₊🐾'; 
    color: var(--accent-soft); 
    position: absolute; 
    top: 50%; left: 50%; 
    transform: translate(-50%, -50%); 
    width: max-content; 
    max-width: 60%; 
    text-align: center; 
    font-family: var(--font-english-script); 
    font-size: clamp(0.9rem, 1.5vw, 1.2rem); 
    pointer-events: none; 
    white-space: nowrap; 
    overflow: hidden; 
    text-overflow: ellipsis;
    opacity: 0.6; 
    animation: sleepy-glow 4s infinite alternate;
}
@keyframes sleepy-glow { 0% { opacity: 0.4; } 100% { opacity: 1; text-shadow: 0 0 8px rgba(91, 164, 229, 0.5); } }

/* 底栏图标彻底替换，保证不消失 */
#options_button *, #send_but *, #extensionsMenuButton *, #ai_retry_button *, #auto_completion_button *, #mes_impersonate * { display: none !important; }

#options_button, #send_but, #extensionsMenuButton, #ai_retry_button, #auto_completion_button, #mes_impersonate { 
    display: inline-flex !important;
    width: 38px !important; height: 38px !important; min-width: 38px !important;
    background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; 
    transition: transform 0.3s ease; font-size: 0 !important; border: none !important; background-color: transparent !important; 
    box-shadow: none !important; padding: 0 !important; color: transparent !important;
}

#options_button:hover, #send_but:hover, #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover, #mes_impersonate:hover { 
    transform: scale(1.15) rotate(5deg); 
    filter: drop-shadow(0 0 8px rgba(91, 164, 229, 0.6)); 
}

#options_button, #send_but, #ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260508/ST9w/1173X694/2026-05-08%2520173237.png/webp') !important; }
#extensionsMenuButton, #auto_completion_button, #mes_impersonate { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260508/WRPO/1461X1448/2026-05-08%2520172827.png/webp') !important; }

/* --- 6. 核心：消息框 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 100px auto 50px !important; 
    width: 90%; max-width: 800px; 
    background-color: var(--card-bg) !important;
    border-radius: 12px !important;
    position: relative;
}

/* --- 独立剥离的名字胶囊 --- */
.mes > .ch_name, .mes .mes_block > .ch_name { 
    display: flex !important; position: absolute; 
    top: -45px !important; 
    width: max-content !important; 
    background: rgba(255, 255, 255, 0.9) !important; 
    border: 1px solid rgba(137, 180, 216, 0.3) !important; 
    border-radius: 20px !important; 
    padding: 6px 16px !important; 
    z-index: 40 !important;
    align-items: center !important;
    gap: 12px !important;
    box-shadow: 0 4px 10px rgba(91, 164, 229, 0.1) !important;
}
.mes[is_user="false"] > .ch_name, .mes[is_user="false"] .mes_block > .ch_name { right: 20px !important; left: auto !important; }
.mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { left: 20px !important; right: auto !important; }

.mes .ch_name > .flex-container { display: flex !important; align-items: center !important; gap: 10px !important; }
.mes .ch_name .name_text { font-family: var(--font-english-serif); font-size: 16px !important; letter-spacing: 1px; color: var(--accent-blue) !important; font-weight: 600; text-shadow: none !important; }

/* --- 独立居中的楼层信息与华丽装饰 --- */
.mes .mesIDDisplay {
    position: absolute !important;
    top: -20px !important; /* 悬浮在背景图正上方中心 */
    left: 50% !important;
    transform: translateX(-50%) !important;
    background: rgba(255, 255, 255, 0.75) !important;
    backdrop-filter: blur(4px) !important;
    -webkit-backdrop-filter: blur(4px) !important;
    padding: 6px 18px !important;
    border-radius: 20px !important;
    border: 1px solid rgba(137, 180, 216, 0.4) !important;
    z-index: 20 !important;
    color: var(--accent-blue) !important;
    font-size: 13px !important;
    font-family: var(--font-english-serif) !important;
    letter-spacing: 1px !important;
    font-weight: 600 !important;
    white-space: nowrap !important;
    box-shadow: 0 4px 12px rgba(91, 164, 229, 0.15) !important;
}
.mesIDDisplay::before { content: '✦ 🐾 Sweet Dream Fragment ✦ No. ' !important; }
.mesIDDisplay::after { content: ' ☾⋆⁺₊' !important; }

/* --- 独立居中的时间戳 (位于楼层正下方) --- */
.mes .mes_timer, .mes .mes_timestamp {
    position: absolute !important;
    top: 48px !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    background: rgba(255, 255, 255, 0.6) !important;
    padding: 2px 12px !important;
    border-radius: 12px !important;
    z-index: 20 !important;
    color: var(--accent-soft) !important;
    font-size: 11px !important;
    font-family: var(--font-english-serif) !important;
    font-weight: 600 !important;
    white-space: nowrap !important;
}

/* 消息框顶部拉长背景横幅 */
.mes .mesAvatarWrapper {
    display: block; padding: 0;
    width: 100%; height: 250px !important; min-height: 250px !important;
    background-size: cover; background-position: center 30%; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-bottom: 1px solid rgba(91, 164, 229, 0.2);
    border-radius: 12px 12px 0 0;
}
/* AI 横幅 */
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260508/a50t/1290X1135/2026-05-08%2520171629.png/webp'); }
/* User 横幅 */
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260508/a50t/1290X1135/2026-05-08%2520171629.png/webp'); }

/* 悬浮头像框 */
.mes .avatar {
    position: absolute;
    top: -60px; 
    width: 100px; height: 100px; 
    background: rgba(255, 255, 255, 0.9) !important; 
    padding: 4px !important; 
    z-index: 30; display: flex !important; align-items: center; justify-content: center;
    border-radius: 50% !important; 
    border: 2px solid rgba(255, 255, 255, 0.9) !important;
    animation: avatar-breathe 5s infinite ease-in-out;
}
.mes[is_user="false"] .avatar { left: 20px; box-shadow: 0 8px 20px rgba(91, 164, 229, 0.2) !important; }
.mes[is_user="true"] .avatar { right: 20px; left: auto; box-shadow: 0 8px 20px rgba(91, 164, 229, 0.2) !important; }
.mes .avatar img { 
    width: 100% !important; height: 100% !important; 
    object-fit: cover !important; border-radius: 50% !important; 
}
@keyframes avatar-breathe {
    0% { transform: translateY(0); } 50% { transform: translateY(-4px); } 100% { transform: translateY(0); }
}

/* --- 右下角点缀贴图 --- */
/* AI贴图 */
.mes[is_user="false"] .mes_block::before {
    content: ''; position: absolute; bottom: -20px; right: -15px;
    width: 140px; height: 140px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260508/6TMp/1321X1854/2026-05-08%2520172801.png/webp');
    background-size: contain; background-repeat: no-repeat; background-position: bottom right;
    z-index: 0 !important; pointer-events: none; opacity: 0.95;
    animation: snoopy-float-right 4s infinite ease-in-out alternate;
}
/* 用户贴图 */
.mes[is_user="true"] .mes_block::before {
    content: ''; position: absolute; bottom: -20px; right: -15px;
    width: 160px; height: 160px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260508/dqNa/1632X1090/2026-05-08%2520172747.png/webp');
    background-size: contain; background-repeat: no-repeat; background-position: bottom right;
    z-index: 0 !important; pointer-events: none; opacity: 0.95;
    animation: snoopy-float-right 5s infinite ease-in-out alternate-reverse;
}
@keyframes snoopy-float-right { 0% { transform: translateY(0) rotate(0deg); } 100% { transform: translateY(-6px) rotate(2deg); } }

/* 消息主体区文字 */
.mes .mes_block { background-color: transparent !important; background-image: none !important; padding: 40px 40px 50px 40px !important; position: relative; border: none !important; overflow: visible !important; min-height: 120px !important; z-index: 10; }
.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; position: relative; z-index: 10 !important; }

/* 背景隐约的水印 */
.mes_block::after {
    content: 'SWEET DREAMS \A STARRY NIGHT'; white-space: pre;
    position: absolute; top: 30px; color: rgba(91, 164, 229, 0.08);
    font-family: var(--font-english-serif); font-size: 32px; text-align: left; font-weight: bold; letter-spacing: 4px;
    z-index: 0; pointer-events: none; user-select: none;
}
.mes[is_user="false"] .mes_block::after { left: 40px; }
.mes[is_user="true"] .mes_block::after { left: 40px; }

/* 思维链自定义 (精细化小号字体) */
summary.mes_reasoning_summary, .mes_reasoning_header { 
    background: transparent !important; border: none !important; padding: 0 !important; margin-bottom: 10px !important; 
}
/* 隐藏默认图标和文字 */
summary.mes_reasoning_summary *, .mes_reasoning_header h4, .mes_reasoning_header_title { 
    font-size: 0 !important; visibility: hidden; display: none !important;
}
summary.mes_reasoning_summary::before, .mes_reasoning_header::before { 
    content: "🐾 Snoopy is having a sweet dream... ☾⋆⁺₊"; 
    font-family: var(--font-english-script); 
    font-size: 15px !important; 
    color: var(--accent-blue); visibility: visible; letter-spacing: 1px; 
    display: block !important;
}
.mes_reasoning { padding-left: 20px !important; margin-bottom: 30px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 1.05em; position: relative; }
.mes_reasoning::before { 
    content: ''; position: absolute; left: 0; top: 5px; bottom: 5px; width: 3px; 
    background: linear-gradient(to bottom, transparent, var(--accent-blue), transparent);
    border-radius: 2px;
}
.mes .mes_text { line-height: 2.3; color: var(--text-main); font-size: 16px; text-align: justify; letter-spacing: 0.5px; }

/* --- 消息按钮组 (精确打击：编辑与更多按钮贴图替换) --- */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 10px; opacity: 0; transition: opacity 0.4s ease; pointer-events: auto !important; margin-top: 15px; position: relative; z-index: 15; align-items: center; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }

/* 深度替换目标贴图 */
.mes .mes_button.mes_edit, 
.mes .mes_button.extraMesButtonsHint {
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    width: 36px !important; 
    height: 36px !important;
    padding: 0 !important;
    transition: transform 0.3s ease !important;
    color: transparent !important;
}

/* 彻底抹除旧图标 */
.mes .mes_button.mes_edit::before, .mes .mes_button.extraMesButtonsHint::before,
.mes .mes_button.mes_edit *, .mes .mes_button.extraMesButtonsHint * {
    display: none !important;
}

/* 赋予新贴纸 */
.mes .mes_button.mes_edit {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260508/7fd1/1461X1095/2026-05-08%2520181918.png/webp') !important;
    background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important;
}
.mes .mes_button.extraMesButtonsHint {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260508/E7U5/1417X999/2026-05-08%2520181843.png/webp') !important;
    background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important;
}

.mes .mes_button.mes_edit:hover, .mes .mes_button.extraMesButtonsHint:hover {
    transform: scale(1.25) rotate(-8deg) !important;
    background-color: transparent !important;
}

/* 其他辅助按钮保留原样式 */
.mes .mes_buttons .mes_button:not(.mes_edit):not(.extraMesButtonsHint), .mes .mes_edit_buttons .mes_button:not(.mes_edit):not(.extraMesButtonsHint) { background-color: rgba(255, 255, 255, 0.9) !important; color: var(--accent-blue) !important; padding: 6px !important; border-radius: 50% !important; cursor: pointer; transition: all 0.3s ease; font-size: 14px !important; border: none !important; }
.mes .mes_buttons .mes_button:not(.mes_edit):not(.extraMesButtonsHint):hover, .mes .mes_edit_buttons .mes_button:not(.mes_edit):not(.extraMesButtonsHint):hover { background-color: var(--accent-blue) !important; color: #fff !important; transform: scale(1.1) rotate(10deg); }

/* 打字指示器 */
#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260508/ST9w/1173X694/2026-05-08%2520173237.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: avatar-breathe 2s infinite ease-in-out, sleepy-glow 2s infinite alternate; border: none !important; height: 50px !important; width: 60px !important; margin: 15px auto !important; }
#typing_indicator .dot { display: none !important; }

/* --- 全局UI设定 (无阴影) --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: rgba(255, 255, 255, 0.6) !important; border-radius: 8px !important; padding: 12px 18px !important; margin-bottom: 10px !important; color: var(--text-main) !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: rgba(255,255,255,0.7) !important; color: var(--text-main) !important; border-radius: 8px !important; padding: 10px !important; border: 1px solid rgba(137, 180, 216, 0.3) !important; font-family: var(--font-english-serif); }
input:focus, textarea:focus, select:focus { outline: none !important; background-color: rgba(255,255,255,1) !important; border: 1px solid var(--accent-blue) !important; }
.menu_button { background-color: rgba(255, 255, 255, 0.6) !important; color: var(--accent-blue) !important; transition: all 0.4s ease; border-radius: 8px !important; font-weight: 600; }
.menu_button:hover { background-color: var(--accent-soft) !important; color: white !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-blue) !important; }

dialog.popup { background-color: transparent !important; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(255, 255, 255, 0.88); z-index: 0; border-radius: 12px; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-blue) !important; color: #fff !important; letter-spacing: 1px; }

/* 手机端适配调整 */
@media (max-width: 768px) {
    .mes { margin: 80px auto 40px !important; }
    .mes > .ch_name, .mes .mes_block > .ch_name { top: -45px !important; padding: 4px 12px !important; }
    .mes .ch_name .name_text { font-size: 15px !important; }

    /* 手机端居中楼层信息调整 */
    .mes .mesIDDisplay { top: 10px !important; font-size: 11px !important; padding: 4px 14px !important; }
    .mes .mes_timer, .mes .mes_timestamp { top: 38px !important; font-size: 9px !important; }

    .mes[is_user="false"] .mes_block::before, .mes[is_user="true"] .mes_block::before { width: 100px; height: 100px; bottom: -15px; right: -10px; } 
    .mes .avatar { width: 80px; height: 80px; top: -40px; }
    .mes .mesAvatarWrapper { height: 160px !important; min-height: 160px !important; }
    .mes_block::after { font-size: 22px; left: 20px !important; }
}

#dialogue_popup { z-index: 10000 !important; pointer-events: auto !important; }
#dialogue_del_mes_ok, #dialogue_del_mes_cancel { background-color: rgba(255,255,255,0.9) !important; color: var(--accent-blue) !important; border-radius: 8px !important; padding: 12px 24px !important; margin: 10px 8px !important; transition: all 0.4s ease !important; border: 1px solid rgba(137, 180, 216, 0.3) !important; font-weight: bold; }
#dialogue_del_mes_ok:hover { background-color: var(--accent-blue) !important; color: #fff !important; transform: translateY(-2px) !important; border-color: transparent !important; }
#dialogue_del_mes_cancel:hover { background-color: var(--accent-soft) !important; color: #fff !important; transform: translateY(-2px) !important; border-color: transparent !important; }
